/** One explicitly reviewed new protocol on an already saved, reset physical VPS.
 * All installation and first-connection actions use visible controls. No draft
 * IDs, root identities, installer calls, account mutations or reset fallbacks.
 * Retains the confirmed owner for later sharing/runtime gates; never restores
 * an old catalog over real server changes, and never retries a recorded attempt. */
@RunWith(AndroidJUnit4.class)
public final class StandaloneProtocolInstallUiIntegrationTest {
    private static final String ACTION="standalone-protocol-install";
    private static final Set<String> ALLOWED=new HashSet<>(Arrays.asList("awg","openvpn","xray"));
    private final UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());

    private UiObject2 visible(BySelector selector,long timeout){UiObject2 view=device.wait(Until.findObject(selector),timeout);assertNotNull("A required standalone installation control did not appear",view);return view;}
    private static Gateway node(List<Gateway> nodes,String id){for(Gateway node:nodes)if(id.equals(node.get("id")))return node;return null;}
    private static Set<String> strings(JSONArray values)throws Exception{Set<String> out=new TreeSet<>();for(int i=0;i<values.length();i++)assertTrue("A protocol occurs twice in the fixture",out.add(values.getString(i)));return out;}
    private static Set<String> ids(List<Gateway> values){Set<String> out=new TreeSet<>();for(Gateway value:values)out.add(value.get("id"));return out;}
    private static String assetHash(Context context,String name)throws Exception{try(InputStream in=context.getAssets().open(name)){java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");byte[] buffer=new byte[65536];int count;while((count=in.read(buffer))!=-1)hash.update(buffer,0,count);StringBuilder out=new StringBuilder();for(byte value:hash.digest())out.append(String.format(Locale.ROOT,"%02x",value&255));return out.toString();}}
    private static Map<String,String> nativeFiles(Context context)throws Exception{TreeMap<String,String> result=new TreeMap<>();File[] files=new File(context.getNoBackupFilesDir(),"vpn-profiles").listFiles();if(files!=null)for(File file:files){assertTrue("Unexpected native-profile store entry",file.isFile());result.put(file.getName(),PrivateAdministrationFixture.hash(file));}return result;}
    private static void sameOriginalNative(Context context,Map<String,String> before)throws Exception{Map<String,String> after=nativeFiles(context);for(Map.Entry<String,String> entry:before.entrySet())assertEquals("An original encrypted native profile changed",entry.getValue(),after.get(entry.getKey()));}
    private static void identity(Gateway actual,JSONObject plan)throws Exception{
        assertFalse("A pair is outside this standalone fixture",actual.isPair());assertFalse(actual.data.optBoolean("clientOnly"));assertFalse(actual.data.optBoolean("adminAccess"));assertEquals("root",actual.get("admin"));
        assertEquals(plan.getString("server_host"),actual.get("host"));assertEquals(plan.getInt("ssh_port"),actual.port());assertEquals(plan.getString("ssh_fingerprint"),actual.get("fingerprint"));assertEquals(plan.getString("machine"),actual.get("machine"));assertEquals(plan.getString("server_name"),ServerProtocols.name(actual));
        assertTrue("The already saved administrator password must remain remembered",actual.remember());assertFalse("The fixture may not provide an alternate root identity",actual.sshPassword.isEmpty());assertNull("This acceptance uses the independently reachable physical server, not a relay",actual.sshRelay);
    }
    /** This guard checks the existing catalog/pin before the normal strict SSH
     * constructor can send authentication, then checks the authenticated machine. */
    private static Ssh guardedSsh(PrivateAdministrationFixture f,Gateway target,JSONObject plan)throws Exception{
        identity(target,plan);assertEquals(plan.getString("ssh_fingerprint"),new ServerIdentityPins(f.context).get(target));Ssh ssh=new Ssh(target);
        try{JSONObject probe=ssh.probe();assertEquals("Authenticated machine differs from the reviewed reset handoff",plan.getString("machine"),probe.getString("machine"));assertEquals("ubuntu",probe.getString("os"));assertEquals(plan.getString("ubuntu_version"),probe.getString("version"));assertFalse("The physical server still owns a Double VPN",probe.optBoolean("pair_helper"));assertFalse("An unreviewed IKEv2 gateway remains",probe.optBoolean("gateway"));return ssh;}catch(Exception|AssertionError failure){ssh.close();throw failure;}
    }
    private static JSONObject inventory(PrivateAdministrationFixture f,Gateway target,JSONObject plan)throws Exception{try(Ssh ssh=guardedSsh(f,target,plan);InputStream recipe=f.context.getAssets().open("single_bundle.zip")){JSONObject result=ssh.single(recipe,new JSONObject().put("action","inspect"));assertTrue(result.getBoolean("compatible_os"));assertFalse("A pair-owned server must be released through its managed reset first",result.getBoolean("pair_node"));assertFalse(result.getBoolean("owned_ikev2"));JSONObject job=result.optJSONObject("job");assertFalse("Inspect the existing operation; do not replay installation",job!=null&&Arrays.asList("starting","running").contains(job.optString("state")));return result;}}
    private static JSONObject status(PrivateAdministrationFixture f,Gateway target,JSONObject plan,String protocol)throws Exception{try(Ssh ssh=guardedSsh(f,target,plan);InputStream recipe=f.context.getAssets().open("single_bundle.zip")){return ssh.single(recipe,new JSONObject().put("action","status").put("protocol",protocol));}}
    private static final String STATE_HASHES="import hashlib,json,pathlib,sys\nq=json.load(sys.stdin); result={}\nfor protocol in q['protocols']:\n assert protocol in ('awg','openvpn','xray')\n p=pathlib.Path('/var/lib/rookstride-single')/protocol/'state.json'\n assert p.is_file() and not p.is_symlink() and p.stat().st_uid==0 and p.stat().st_size<=4194304\n result[protocol]=hashlib.sha256(p.read_bytes()).hexdigest()\nprint(json.dumps(result,sort_keys=True))";
    private static JSONObject stateHashes(PrivateAdministrationFixture f,Gateway target,JSONObject plan,Set<String> protocols)throws Exception{try(Ssh ssh=guardedSsh(f,target,plan)){return new JSONObject(ssh.execute("python3 -c "+InputRules.quote(STATE_HASHES),new JSONObject().put("protocols",new JSONArray(protocols)).toString()));}}
    private static void resetHandoff(PrivateAdministrationFixture f,JSONObject plan)throws Exception{
        String name=plan.getString("reset_handoff_file");assertTrue("Reset handoff must be a private basename",name.matches("[A-Za-z0-9_-]{1,96}\\.json"));File file=f.file(name);assertTrue(file.isFile());assertFalse("Reset handoff cannot be a link",Files.isSymbolicLink(file.toPath()));assertTrue(file.length()>0&&file.length()<=262144);byte[] bytes=Files.readAllBytes(file.toPath());assertEquals("Use the exact observed managed-reset handoff",plan.getString("reset_handoff_sha256"),PrivateAdministrationFixture.hash(bytes));JSONObject reset=new JSONObject(new String(bytes,StandardCharsets.UTF_8));
        assertEquals(1,reset.getInt("schema"));assertTrue("Actual managed reset must have completed and been inspected",reset.getBoolean("managed_reset_verified"));assertTrue(reset.getBoolean("empty_inventory_verified"));assertEquals("The reset must belong to this exact app",f.binary.getString("apk_sha256"),reset.getJSONObject("binary").getString("apk_sha256"));JSONObject physical=reset.getJSONObject("server");
        for(String field:new String[]{"id","host","fingerprint","machine"})assertEquals("The reset belongs to another saved physical server",plan.getString(field.equals("id")?"server_node_id":field.equals("host")?"server_host":field.equals("fingerprint")?"ssh_fingerprint":field),physical.getString(field));
    }
    private static void preserveOriginals(PrivateAdministrationFixture f,List<Gateway> original,Map<String,String> originalNative)throws Exception{
        ArrayList<Gateway> current=new Vault(f.context).read();for(Gateway old:original){Gateway saved=node(current,old.get("id"));assertNotNull("An original catalog record disappeared",saved);for(String field:new String[]{"host","admin","fingerprint","machine","protocol","serverInstance","vpnLogin","profileUuid","coexistPair"})assertEquals("Installation changed an original connection identity",old.get(field),saved.get(field));assertTrue("Original saved root password changed",old.sshPassword.equals(saved.sshPassword));assertTrue("Original saved SSH key changed",old.privateKey.equals(saved.privateKey));assertTrue("Original saved VPN password changed",old.vpnPassword.equals(saved.vpnPassword));}sameOriginalNative(f.context,originalNative);
    }
    private void openServer(JSONObject plan){onView(withContentDescription("Servers")).perform(click());onView(allOf(withContentDescription("Manage "+plan.optString("server_name")),isDescendantOfA(withTagValue(is((Object)("managed-server-"+plan.optString("server_node_id"))))))).perform(scrollTo(),click());}
    private void phase(PrivateAdministrationFixture f,JSONObject receipt,File marker,String phase,DeploymentService.Session session)throws Exception{receipt.put("phase",phase);if(session!=null){receipt.put("owner_node_id",session.node.get("id")).put("progress",session.progress.json());if(!session.node.get("job").isEmpty()){assertTrue("A different remote job replaced the authorized installation",receipt.optString("server_job").isEmpty()||receipt.optString("server_job").equals(session.node.get("job")));receipt.put("server_job",session.node.get("job"));}}f.receipt("standalone-install-progress.json",new JSONObject(receipt.toString()));PrivateAdministrationFixture.atomic(marker,receipt.toString().getBytes(StandardCharsets.UTF_8));}
    private void failIfAttention(){for(String title:new String[]{"Action needs attention","Server sign-in was rejected","Check this server's identity","Server identity changed","Review this server"})if(device.hasObject(By.text(title)))throw new AssertionError("Visible installation needs attention; retain its existing operation and inspect without replaying setup");}
    private DeploymentService.Session started(DeploymentService.Session previous,JSONObject plan)throws Exception{long end=SystemClock.elapsedRealtime()+30000;while(SystemClock.elapsedRealtime()<end){DeploymentService.Session active=DeploymentService.current();if(active!=null&&active!=previous){assertEquals("protocol",active.progress.kind);assertEquals(plan.getString("protocol"),active.node.get("protocol"));identity(active.node,plan);assertFalse(active.resume);return active;}failIfAttention();Thread.sleep(100);}throw new AssertionError("No new foreground operation was observed; inspect before trying again");}
    private static void progressViews(View view,Set<String> labels,boolean[] found){if(view instanceof TextView)labels.add(((TextView)view).getText().toString());Object tag=view.getTag();if(tag instanceof String&&((String)tag).startsWith("installation-rook-"))found[0]=true;if(view instanceof ProgressBar&&((ProgressBar)view).getMax()==InstallationProgress.PROTOCOL.length)found[1]=true;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)progressViews(((ViewGroup)view).getChildAt(i),labels,found);}
    private void installationProgress(ActivityScenario<RookstrideActivity> screen,DeploymentService.Session session){assertEquals("The seven actual protocol checkpoints must be exposed",7,session.progress.steps().length);onView(withTagValue(is((Object)"installation-progress-card"))).check(matches(isDisplayed()));screen.onActivity(activity->{Set<String> labels=new HashSet<>();boolean[] found=new boolean[2];progressViews(activity.findViewById(android.R.id.content),labels,found);for(String step:InstallationProgress.PROTOCOL)assertTrue("A real installation checkpoint is missing from the view",labels.contains(step));assertTrue("The active checkpoint needs its Rook illustration",found[0]);assertTrue("The bounded checkpoint progress bar is missing",found[1]);});}
    @SuppressWarnings("deprecation")
    private static void foreground(Context context)throws Exception{long end=SystemClock.elapsedRealtime()+10000;ActivityManager manager=context.getSystemService(ActivityManager.class);while(SystemClock.elapsedRealtime()<end){for(ActivityManager.RunningServiceInfo service:manager.getRunningServices(64))if(service.service.getClassName().equals(DeploymentService.class.getName())&&service.foreground&&service.uid==context.getApplicationInfo().uid)return;Thread.sleep(100);}throw new AssertionError("The installation did not enter the real foreground service");}
    private void complete(PrivateAdministrationFixture f,JSONObject receipt,File marker,DeploymentService.Session session)throws Exception{long end=SystemClock.elapsedRealtime()+30*60*1000L;String last="";while(SystemClock.elapsedRealtime()<end){assertSame("Another operation replaced the visible installation",session,DeploymentService.current());String current=session.progress.state+":"+session.progress.completed+":"+session.progress.phase;if(!current.equals(last)){phase(f,receipt,marker,"foreground installation",session);last=current;}if(!session.progress.state.equals("running")){assertEquals("Server setup needs attention; preserve its job rather than replaying installation","complete",session.progress.state);assertNull(session.error);assertFalse(DeploymentService.needsLocalSave());return;}failIfAttention();Thread.sleep(250);}throw new AssertionError("The recorded installation is still pending; resume that operation after review, never replay this test");}
    private static Gateway installed(Context context,DeploymentService.Session session)throws Exception{Gateway saved=node(new Vault(context).read(),session.node.get("id"));assertNotNull("Confirmed owner was not durably saved",saved);assertFalse(saved.data.optBoolean("clientOnly"));assertFalse(saved.get("serverInstance").isEmpty());assertEquals(session.result.getString("instance"),saved.get("serverInstance"));assertEquals("this-phone",saved.get("vpnLogin"));return saved;}
    private JSONObject monitoring(PrivateAdministrationFixture f,Gateway saved,JSONObject plan)throws Exception{long end=SystemClock.elapsedRealtime()+45000;JSONObject result=null;while(SystemClock.elapsedRealtime()<end){result=status(f,saved,plan,saved.get("protocol"));assertEquals(saved.get("serverInstance"),result.getString("instance"));assertTrue(result.getBoolean("running"));assertTrue("Shared ad blocking did not start",result.getJSONObject("filtering").getBoolean("running"));if(result.optBoolean("monitoring_available"))return result;Thread.sleep(1000);}throw new AssertionError("The installed protocol's usage monitoring did not become available");}
    private void nativeConsent(Context context,Gateway saved)throws Exception{
        // The ordinary Connect action may still be fetching the existing profile
        // over SSH. Handle prompts when they actually appear, rather than assuming
        // their timing or bypassing the app's battery/Android consent choices.
        long end=SystemClock.elapsedRealtime()+90000;
        while(SystemClock.elapsedRealtime()<end){
            UiObject2 battery=device.findObject(By.text("Connect now"));if(battery!=null)battery.click();UiObject2 consent=device.findObject(By.pkg("com.android.vpndialogs").res("android:id/button1"));if(consent!=null)consent.click();failIfAttention();
            NativeVpn.Status status=NativeVpn.status(context,saved.get("protocol"));if(status.id.equals(saved.get("id"))&&Arrays.asList("connected","limited","failed","error").contains(status.state))return;Thread.sleep(150);
        }
        throw new AssertionError("The ordinary first connection did not finish; preserve its saved owner/profile for inspection");
    }
    private static void disconnected(Context context,Gateway node)throws Exception{long end=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<end){NativeVpn.Status state=NativeVpn.status(context,node.get("protocol"));if(!state.active(node.get("id")))return;Thread.sleep(150);}throw new AssertionError("The new test tunnel did not stop; its confirmed owner/profile have been retained");}

    @Test public void visibleNewStandaloneProtocolSurvivesBackgroundAndRetainsItsRealOwnerAndProfile()throws Exception{
        PrivateAdministrationFixture f=PrivateAdministrationFixture.load(ACTION,"allow_standalone_install_ui");JSONObject plan=f.request.getJSONObject("standalone_install");String protocol=plan.getString("protocol"),attempt=plan.getString("attempt_id");assertEquals("Use the exact reviewed instrumentation APK",f.request.getString("expected_test_apk_sha256"),f.binary.getString("test_apk_sha256"));
        assertTrue("Only the three reviewed standalone protocols are in scope",ALLOWED.contains(protocol));assertTrue(attempt.matches("[a-f0-9]{32}"));assertTrue(plan.getBoolean("new_disposable_protocol"));assertTrue(plan.getBoolean("exclusive_test_phone"));assertTrue("First native connection needs explicit authorization",f.request.getBoolean("allow_native_vpn"));assertEquals("all",AppRouting.read(f.context).mode);assertFalse(DeploymentService.needsLocalSave());assertFalse(ConnectionBundleImport.recoveryPending(f.context));assertTrue(plan.getString("machine").matches("[a-f0-9]{64}"));assertTrue(plan.getString("ssh_fingerprint").matches("SHA256:[A-Za-z0-9+/]{43}"));
        File marker=f.file("standalone-install-attempt-"+attempt+".json");assertFalse("This attempt already ran; inspect its retained job/owner instead of replaying setup",marker.exists());ConnectivityManager cm=f.context.getSystemService(ConnectivityManager.class);NetworkCapabilities network=cm.getNetworkCapabilities(cm.getActiveNetwork());assertTrue("Stop the previous VPN before this installation/first connection",network==null||!network.hasTransport(NetworkCapabilities.TRANSPORT_VPN));
        JSONObject recipes=plan.getJSONObject("recipe_sha256");assertEquals(1,recipes.length());assertEquals("Pin the exact recipe packaged in the signed app",recipes.getString("single_bundle.zip"),assetHash(f.context,"single_bundle.zip"));resetHandoff(f,plan);
        ArrayList<Gateway> original=new Vault(f.context).read();Gateway physical=node(original,plan.getString("server_node_id"));assertNotNull("The real physical server must already be saved; this test does not manufacture catalog identities",physical);identity(physical,plan);assertTrue(physical.get("job").isEmpty());Set<String> expected=strings(plan.getJSONArray("installed_protocols"));assertTrue(ALLOWED.containsAll(expected));assertFalse("Requested protocol already exists; inspect or explicitly reset it instead",expected.contains(protocol));assertEquals(expected,ServerProtocols.installed(original,physical));
        for(Gateway saved:original){assertFalse("The server is still a member of a saved Double VPN",saved.isPair()&&(PairNodes.same(saved,physical)||PairNodes.same(saved.exit,physical)));if(ServerProtocols.sameServer(saved,physical)){assertTrue("Unreviewed saved protocol exists on this physical server",saved.get("protocol").isEmpty()||expected.contains(saved.get("protocol")));assertTrue(saved.get("job").isEmpty());assertTrue("Previous pair ownership remains on a standalone record",saved.get("coexistPair").isEmpty());}}
        JSONObject preflight=inventory(f,physical,plan);assertEquals(expected,strings(preflight.getJSONArray("installed_protocols")));JSONObject expectedInstances=plan.getJSONObject("installed_instances");assertEquals(expected.size(),expectedInstances.length());for(String present:expected){String instance=expectedInstances.getString(present);assertEquals(instance,preflight.getJSONObject("installed_instances").getString(present));Gateway owner=ServerProtocols.find(original,physical,present);assertNotNull("Every installed protocol must already have its real owner record",owner);assertEquals(instance,owner.get("serverInstance"));assertTrue(status(f,owner,plan,present).getBoolean("running"));}
        JSONObject originalState=stateHashes(f,physical,plan,expected);Map<String,String> originalNative=nativeFiles(f.context);Set<String> originalIds=ids(original);String originalPassword=physical.sshPassword,originalKey=physical.privateKey;DeploymentService.Session previous=DeploymentService.current(),session=null;assertTrue("Finish or explicitly abandon the previous recorded operation first",previous==null||previous.progress.state.equals("complete"));Gateway created=null;boolean connectTapped=false,passed=false;JSONObject receipt=new JSONObject().put("binary",new JSONObject(f.binary.toString())).put("action",ACTION).put("attempt_id",attempt).put("protocol",protocol).put("server_node_id",physical.get("id")).put("recipe_sha256",recipes).put("reset_handoff_sha256",plan.getString("reset_handoff_sha256")).put("independent_uid_traffic_tested",false).put("native_client_connected",false);
        assertTrue("Another test consumed this exact attempt",marker.createNewFile());phase(f,receipt,marker,"preflight verified; installation not yet started",null);
        try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){
            openServer(plan);visible(By.text("Add protocol").enabled(true),90000);onView(withText("Add protocol")).perform(scrollTo(),click());onView(allOf(withText(SingleProtocols.from(protocol).title),isAssignableFrom(Button.class))).inRoot(isDialog()).perform(scrollTo(),click());onView(withText("Not installed")).check(matches(isDisplayed()));onView(allOf(withText("Install VPN"),isDescendantOfA(withTagValue(is((Object)"connection-controls"))))).perform(scrollTo(),click());
            session=started(previous,plan);assertFalse("A newly selected protocol must receive its own actual catalog identity",originalIds.contains(session.node.get("id")));UUID.fromString(session.node.get("id"));assertEquals(protocol,session.config.getString("protocol"));assertEquals("this-phone",session.config.getString("login"));if(protocol.equals("openvpn")){assertEquals("password",session.config.getString("access_mode"));assertFalse(session.node.vpnPassword.isEmpty());}
            phase(f,receipt,marker,"visible seven-step installation started",session);installationProgress(screen,session);foreground(f.context);receipt.put("visible_seven_checkpoint_progress",true).put("actual_foreground_service",true);long started=session.progress.started;onView(withContentDescription("Journal")).perform(click());visible(By.text("Coming soon"),10000);screen.recreate();assertSame(session,DeploymentService.current());screen.moveToState(Lifecycle.State.CREATED);Thread.sleep(1500);assertSame(session,DeploymentService.current());screen.moveToState(Lifecycle.State.RESUMED);assertEquals(started,session.progress.started);onView(withContentDescription(session.progress.state.equals("complete")?"View completed installation":"View installation progress")).perform(click());if(session.progress.state.equals("running"))installationProgress(screen,session);receipt.put("journal_background_recreation_kept_same_operation",true);
            complete(f,receipt,marker,session);assertNotNull(session.result);assertEquals(7,session.progress.completed);assertTrue(session.progress.finished>=session.progress.started);long finished=session.progress.finished;onView(withTagValue(is((Object)"installation-complete"))).check(matches(isDisplayed()));onView(withText("Done")).perform(click());screen.recreate();assertEquals(finished,session.progress.finished);created=installed(f.context,session);PrivateAdministrationFixture.atomic(f.file("standalone-installed-node-private.json"),created.persisted().toString().getBytes(StandardCharsets.UTF_8));receipt.put("server_install_confirmed",true).put("server_instance",created.get("serverInstance"));phase(f,receipt,marker,"server installation confirmed; verifying modules",session);identity(created,plan);assertTrue("New owner root credential changed",originalPassword.equals(created.sshPassword));assertTrue("New owner SSH private key changed",originalKey.equals(created.privateKey));
            Set<String> all=new TreeSet<>(expected);all.add(protocol);JSONObject after=inventory(f,created,plan);assertEquals(all,strings(after.getJSONArray("installed_protocols")));JSONObject completedJob=after.getJSONObject("job");assertEquals(protocol,completedJob.getString("protocol"));assertEquals("complete",completedJob.getString("state"));assertEquals(7,completedJob.getInt("stage"));assertTrue(InputRules.job(completedJob.getString("job")));assertTrue("A different job was completed",receipt.optString("server_job").isEmpty()||receipt.getString("server_job").equals(completedJob.getString("job")));receipt.put("server_job",completedJob.getString("job"));JSONObject hashes=stateHashes(f,created,plan,expected);for(String present:expected){assertEquals("Installing another protocol changed an existing protocol's users/configuration",originalState.getString(present),hashes.getString(present));assertEquals(expectedInstances.getString(present),after.getJSONObject("installed_instances").getString(present));}preserveOriginals(f,original,originalNative);JSONObject health=monitoring(f,created,plan);assertEquals("A new protocol must contain only its normal initial account",1,health.getJSONArray("users").length());assertEquals("this-phone",health.getJSONArray("users").getJSONObject(0).getString("login"));receipt.put("durable_owner_after_done_and_recreation",true).put("server_instance",created.get("serverInstance")).put("running",true).put("filtering_instance",health.getJSONObject("filtering").getString("instance")).put("monitoring_available",true).put("existing_protocol_state_and_native_identity_unchanged",true);
            phase(f,receipt,marker,"first ordinary Connect fetches the installed account",session);openServer(plan);onView(withContentDescription("Settings for "+SingleProtocols.from(protocol).title)).perform(scrollTo(),click());onView(allOf(withText("Connect"),isDescendantOfA(withTagValue(is((Object)"connection-controls"))))).perform(scrollTo(),click());connectTapped=true;nativeConsent(f.context,created);NativePairIntegrationTest.connected(f.context,created);NativeProfileStore store=new NativeProfileStore(f.context);assertTrue("Ordinary Connect did not cache the real server profile",store.exists(created.get("id")));JSONObject cached=store.read(created.get("id"));assertEquals(protocol,cached.getString("protocol"));NativeProfiles.validate(protocol,cached.getString("content"));String profileHash=PrivateAdministrationFixture.hash(cached.getString("content"));try(Ssh ssh=guardedSsh(f,created,plan);InputStream recipe=f.context.getAssets().open("single_bundle.zip")){JSONObject actual=ssh.single(recipe,new JSONObject().put("action","profile").put("protocol",protocol).put("login",created.get("vpnLogin")));JSONObject expectedProfile=ConnectionCollectionProfiles.complete(actual,created.get("vpnLogin"),created.vpnPassword,"Installed account comparison");assertEquals("The native cache differs from the exact existing installed account",PrivateAdministrationFixture.hash(expectedProfile.getString("content")),profileHash);}screen.recreate();NativePairIntegrationTest.connected(f.context,created);assertEquals(profileHash,PrivateAdministrationFixture.hash(store.read(created.get("id")).getString("content")));receipt.put("native_client_connected",true).put("native_profile_sha256",profileHash);
            if(f.request.optBoolean("allow_independent_probe")){f.context.getPackageManager().getApplicationInfo("io.rookstride.probe",0);NativePairIntegrationTest.verifyTraffic(NativePairIntegrationTest.probe(f.context,false,plan.optString("canary_url")),plan.getString("expected_exit"),plan.optString("canary_token"));receipt.put("independent_uid_traffic_tested",true);}
            onView(allOf(withText("Disconnect"),isDescendantOfA(withTagValue(is((Object)"connection-controls"))))).perform(scrollTo(),click());disconnected(f.context,created);assertEquals(profileHash,PrivateAdministrationFixture.hash(store.read(created.get("id")).getString("content")));created=installed(f.context,session);preserveOriginals(f,original,originalNative);ArrayList<Gateway> current=new Vault(f.context).read();Set<String> added=ids(current);added.removeAll(originalIds);assertEquals("Only the requested real protocol owner may be added",Collections.singleton(created.get("id")),added);assertEquals(all,ServerProtocols.installed(current,created));
            PrivateAdministrationFixture.atomic(f.file("standalone-installed-node-private.json"),created.persisted().toString().getBytes(StandardCharsets.UTF_8));receipt.put("new_owner_retained_for_next_gate",true).put("first_connection_profile_retained",true).put("no_extra_user_creation",true).put("no_reset_or_install_replay",true);passed=true;
        }finally{
            // Disconnect only the newly authorized client. Preserve all original
            // catalog data, the new owner and any real incomplete server job.
            boolean stopped=!connectTapped;try{if(connectTapped&&created!=null){NativeVpn.disconnect(f.context,created.get("protocol"));disconnected(f.context,created);stopped=true;}}finally{receipt.put("passed",passed&&stopped).put("test_tunnel_stopped",stopped);phase(f,receipt,marker,passed&&stopped?"complete; new owner retained":"failed; existing operation and catalog retained for review",session);f.receipt("standalone-install-result.json",receipt);}
        }
    }
}
